// src/components/EventOwner/EventOwnerDashboard.jsx

import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import './EventOwnerDashboard.css';

const EventOwnerDashboard = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const response = await axios.get('http://localhost:5000/api/event'); // Replace with your actual API endpoint
        setEvents(response.data);
      } catch (error) {
        console.error('Error fetching events:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchEvents();
  }, []);

  const handleDeleteEvent = async (eventId) => {
    try {
      await axios.delete(`http://localhost:5000/api/event/${eventId}`); // Replace with your actual API endpoint
      setEvents(events.filter(event => event._id !== eventId)); // Remove the deleted event from the state
    } catch (error) {
      console.error('Error deleting event:', error);
    }
  };

  return (
    <div className="event-owner-dashboard">
      <h1>Event Owner Dashboard</h1>
      <Link to="/eventowner/create-event" className="btn">Create New Event</Link>
      {loading ? (
        <p>Loading events...</p>
      ) : (
        <div className="event-list">
          <h2>Your Events</h2>
          {events.length === 0 ? (
            <p>No events found.</p>
          ) : (
            <ul>
              {events.map(event => (
                <li key={event._id} className="event-item">
                  <h3>{event.name}</h3>
                  <p>Date: {new Date(event.date).toLocaleDateString()}</p>
                  <p>Location: {event.location}</p>
                  <div className="event-actions">
                    <Link to={`/eventowner/edit-event/${event._id}`} className="btn">Edit</Link>
                    <button onClick={() => handleDeleteEvent(event._id)} className="btn btn-danger">Delete</button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
};

export default EventOwnerDashboard;



